const payload = (typeof msg.payload === "object" && msg.payload !== null) ? msg.payload : {};
const deviceId = String(payload.device_id || "").trim();

if (!deviceId) {
    node.warn("Mensaje descartado: falta device_id");
    return null;
}

const co = Number(payload.co_ppm);
const raw_co_adc = Number(payload.raw_co_adc);
if (!Number.isFinite(co)) {
    node.warn(`Mensaje descartado (${deviceId}): co_ppm invalido`);
    return null;
}

const parseThreshold = (rawValue, fallback) => {
    const parsed = Number(rawValue);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

const thresholdSeguroMax = parseThreshold("${CO_SEGURO_MAX_PPM}", 8);
const thresholdPrecaucionMax = parseThreshold("${CO_PRECAUCION_MAX_PPM}", 14);
const thresholdPeligroMax = parseThreshold("${CO_PELIGRO_MAX_PPM}", 22);
const thresholdUrgenteMin = parseThreshold("${CO_URGENTE_MIN_PPM}", thresholdPeligroMax);

const rawPresencia = payload.presencia;
const presencia =
    rawPresencia === true ||
    rawPresencia === 1 ||
    rawPresencia === "1" ||
    String(rawPresencia || "").toUpperCase() === "SI" ||
    String(rawPresencia || "").toLowerCase() === "true";


let estadoBase = "SEGURO";
if (co < 0.5 && raw_co_adc < 80) estadoBase = "SEGURO";
else if (co < 0.8 && raw_co_adc < 100) estadoBase = "PRECAUCION";
else if (co < 1 && raw_co_adc < 120) estadoBase = "PELIGRO";
else estadoBase = "CRITICO";

const urgente = presencia && (co > 1 || raw_co_adc > 120);
const estado = urgente ? `${estadoBase}_URGENTE` : estadoBase;
const timestamp =
    (typeof payload.timestamp === "string" && payload.timestamp.trim().length > 0)
        ? payload.timestamp
        : new Date().toISOString();

msg.telemetry = {
    device_id: deviceId,
    node_type: "unknown",
    timestamp,
    co_ppm: Number(co.toFixed(1)),
    raw_co_adc,
    presencia,
    presencia_text: presencia ? "SI" : "NO",
    estado,
    estado_base: estadoBase,
    urgente,
    thresholds: {
        seguro_max_ppm: thresholdSeguroMax,
        precaucion_max_ppm: thresholdPrecaucionMax,
        peligro_max_ppm: thresholdPeligroMax,
        urgente_min_ppm: thresholdUrgenteMin
    },
    source_topic: msg.topic || "",
    message_id: payload.message_id ?? null
};

msg.payload = msg.telemetry;
return msg;

msg.telemetry.node_type = "hardware";
msg.payload = msg.telemetry;
return msg;

msg.telemetry.node_type = "simulated";
msg.payload = msg.telemetry;
return msg;

const t = msg.telemetry;
msg.topic = "INSERT INTO devices (device_id, node_type, description, last_seen_at) VALUES (?, ?, ?, NOW(3)) ON DUPLICATE KEY UPDATE node_type=VALUES(node_type), description=VALUES(description), last_seen_at=NOW(3)";
msg.payload = [t.device_id, t.node_type, `${t.node_type} node`];
return msg;

const t = msg.telemetry;
msg.topic = "INSERT INTO sensor_readings (device_id, device_timestamp, co_ppm, raw_co_adc, presencia, source_topic, message_id) VALUES (?, ?, ?, ?, ?, ?, ?)";
msg.payload = [t.device_id, t.timestamp, t.co_ppm, t.raw_co_adc, t.presencia ? 1 : 0, t.source_topic, t.message_id];
return msg;

const t = msg.telemetry;
const reason = t.urgente
  ? "Presencia detectada durante nivel crítico de CO"
  : `Clasificación por umbral: ${t.estado_base}`;

msg.topic = "INSERT INTO state_events (device_id, device_timestamp, estado, urgente, co_ppm, presencia, reason) VALUES (?, ?, ?, ?, ?, ?, ?)";
msg.payload = [t.device_id, t.timestamp, t.estado, t.urgente ? 1 : 0, t.co_ppm, t.presencia ? 1 : 0, reason];
return msg;

const t = msg.telemetry;
const parseThreshold = (rawValue, fallback) => {
  const parsed = Number(rawValue);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

const thresholdFromTelemetry = t.thresholds && t.thresholds.peligro_max_ppm;
const criticalThreshold = parseThreshold(
  thresholdFromTelemetry != null ? thresholdFromTelemetry : "${CO_PELIGRO_MAX_PPM}",
  22
);

if (!(t.urgente || t.estado === "PELIGRO" || t.estado === "CRITICO" || t.estado.includes("URGENTE"))) {
  return null;
}

const alertCooldownMs = 75 * 1000;
const cooldownKey = `alert_cooldown:${t.device_id}`;
const lastAlertAt = Number(flow.get(cooldownKey) || 0);
if (Date.now() - lastAlertAt < alertCooldownMs) {
  return null;
}
flow.set(cooldownKey, Date.now());

const severity = t.urgente ? "CRITICAL" : "HIGH";
const message = t.urgente
  ? "CO crítico con presencia detectada."
  : "CO crítico sin presencia detectada.";

msg.alertPayload = {
  device_id: t.device_id,
  timestamp: t.timestamp,
  severity,
  message,
  co_ppm: t.co_ppm,
  raw_co_adc: t.raw_co_adc,
  presencia: t.presencia ? "SI" : "NO",
  estado: t.estado,
  urgente: t.urgente ? 1 : 0
};

msg.topic = "INSERT INTO alerts (device_id, device_timestamp, severity, estado, message, co_ppm, raw_co_adc, presencia, urgente) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)";
msg.payload = [t.device_id, t.timestamp, severity, t.estado, message, t.co_ppm, t.raw_co_adc, t.presencia ? 1 : 0, t.urgente ? 1 : 0];
return msg;

if (!msg.alertPayload) {
  return null;
}

const topicBase = env.get("MQTT_TOPIC_BASE") || "your_maqiatto_username/fiot/garage";
msg.topic = `${topicBase}/alerts`;
msg.payload = JSON.stringify(msg.alertPayload);
return msg;

const t = msg.telemetry;
if (!t || !t.device_id) {
  return null;
}

const commandsEnabledRaw = String(env.get("COMMANDS_ENABLED") || "true").trim().toLowerCase();
const commandsEnabled = !["0", "false", "off", "no"].includes(commandsEnabledRaw);
if (!commandsEnabled) {
  return null;
}

const parseThreshold = (rawValue, fallback) => {
  const parsed = Number(rawValue);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

const safeThreshold = parseThreshold(
  t.thresholds && t.thresholds.seguro_max_ppm,
  parseThreshold("${CO_SEGURO_MAX_PPM}", 8)
);
const criticalThreshold = parseThreshold(
  t.thresholds && t.thresholds.peligro_max_ppm,
  parseThreshold("${CO_PELIGRO_MAX_PPM}", 22)
);

let action = null;
let reason = "";

if (t.urgente || t.co_ppm >= criticalThreshold) {
  action = "ENCENDER";
  reason = "CO en nivel crítico";
} else if (t.co_ppm < safeThreshold) {
  action = "APAGAR";
  reason = "CO volvió a nivel seguro";
}

if (!action) {
  return null;
}

const cacheKey = `ventilation:${t.device_id}`;
const lastAction = flow.get(cacheKey);
if (lastAction === action) {
  return null;
}
flow.set(cacheKey, action);

msg.commandPayload = {
  device_id: t.device_id,
  timestamp: t.timestamp,
  actuator: "VENTILACION",
  action,
  reason,
  source_state: t.estado,
  co_ppm: t.co_ppm,
  presencia: t.presencia ? "SI" : "NO"
};

msg.topic = "INSERT INTO actuator_commands (device_id, device_timestamp, actuator, action, reason, source_state, co_ppm, presencia, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)";
msg.payload = [
  t.device_id,
  t.timestamp,
  "VENTILACION",
  action,
  reason,
  t.estado,
  t.co_ppm,
  t.presencia ? 1 : 0,
  "PUBLISHED"
];

return msg;

if (!msg.commandPayload) {
  return null;
}

const topicBase = env.get("MQTT_TOPIC_BASE") || "your_maqiatto_username/fiot/garage";
const commandTopic = env.get("MQTT_COMMAND_TOPIC") || `${topicBase}/commands/${msg.commandPayload.device_id}`;

msg.topic = commandTopic;
msg.payload = msg.commandPayload;
return msg;

const simId = env.get("SIM_DEVICE_ID") || "SIM-GARAGE-CO-002";
const topicBase = env.get("MQTT_TOPIC_BASE") || "your_maqiatto_username/fiot/garage";

const parseThreshold = (rawValue, fallback) => {
  const parsed = Number(rawValue);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
};

const thresholdSeguroMax = parseThreshold("${CO_SEGURO_MAX_PPM}", 8);
const thresholdPrecaucionMax = parseThreshold("${CO_PRECAUCION_MAX_PPM}", 14);
const thresholdPeligroMax = parseThreshold("${CO_PELIGRO_MAX_PPM}", 22);
const thresholdUrgenteMin = parseThreshold("${CO_URGENTE_MIN_PPM}", thresholdPeligroMax);

const minCo = Math.max(0, thresholdSeguroMax - 2);
const maxCo = Math.max(minCo + 1, thresholdPeligroMax + 23);
const co = Number((minCo + Math.random() * (maxCo - minCo)).toFixed(1));

// Base raw ADC correlates 1:100 with PPM
let raw_co_adc = Math.max(0, Math.min(4095, Math.round(co * 100)));

// 15% chance of a raw-only spike (synthetic noise) to test dual-trigger logic
if (Math.random() < 0.15) {
  raw_co_adc = Math.min(4095, raw_co_adc + Math.floor(Math.random() * 200) + 100);
}

const presencia = Math.random() > 0.55;

let estado = "SEGURO";
if (co < thresholdSeguroMax && raw_co_adc < 80) estado = "SEGURO";
else if (co < thresholdPrecaucionMax && raw_co_adc < 100) estado = "PRECAUCION";
else if (co < thresholdPeligroMax && raw_co_adc < 120) estado = "PELIGRO";
else estado = "CRITICO";

if (presencia && (co > thresholdUrgenteMin || raw_co_adc > 120)) {
  estado += "_URGENTE";
}

msg.topic = `${topicBase}/telemetry`;
msg.payload = {
  device_id: simId,
  timestamp: new Date().toISOString(),
  co_ppm: co,
  raw_co_adc,
  presencia: presencia ? "SI" : "NO",
  estado
};

return msg;

msg.query_name = "latest_sensor_readings";
msg.topic = "SELECT device_id, device_timestamp, co_ppm, raw_co_adc, presencia, ingested_at FROM sensor_readings ORDER BY id DESC LIMIT ?";
msg.payload = [20];
return msg;

