    (SELECT ROUND(COALESCE(AVG(co_ppm), 0), 2) FROM sensor_readings WHERE ingested_at >= DATE_SUB(NOW(3), INTERVAL ? HOUR)${deviceFilter}) AS avg_co_ppm,
    (SELECT COALESCE(MAX(co_ppm), 0) FROM sensor_readings WHERE ingested_at >= DATE_SUB(NOW(3), INTERVAL ? HOUR)${deviceFilter}) AS max_co_ppm,
    (SELECT COALESCE(MIN(co_ppm), 0) FROM sensor_readings WHERE ingested_at >= DATE_SUB(NOW(3), INTERVAL ? HOUR)${deviceFilter}) AS min_co_ppm,
    (SELECT COUNT(*) FROM alerts WHERE alert_ts >= DATE_SUB(NOW(3), INTERVAL ? HOUR)${deviceFilter}) AS total_alerts,
    (SELECT COUNT(*) FROM alerts WHERE alert_ts >= DATE_SUB(NOW(3), INTERVAL ? HOUR) AND severity = 'CRITICAL'${deviceFilter}) AS critical_alerts,
    (SELECT COUNT(*) FROM alerts WHERE alert_ts >= DATE_SUB(NOW(3), INTERVAL ? HOUR) AND ack_status = 'PENDING'${deviceFilter}) AS pending_alerts,
