const toNumberOrNull = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = {
  data: rows.map((row) => ({
    id: Number(row.id),
    device_id: row.device_id,
    command_ts: row.command_ts,
    actuator: row.actuator,
    action: row.action,
    reason: row.reason,
    source_state: row.source_state,
    co_ppm: toNumberOrNull(row.co_ppm),
    presencia: toNumberOrNull(row.presencia),
    status: row.status
  }))
};
return msg;

const body = (typeof msg.payload === "object" && msg.payload !== null) ? msg.payload : {};
const action = String(body.action || "").trim().toUpperCase();

if (action !== "ENCENDER" && action !== "APAGAR") {
  msg.statusCode = 400;
  msg.payload = { error: "validation_error", message: "action must be ENCENDER or APAGAR" };
  return [msg, null, null];
}

const topicBase = env.get("MQTT_TOPIC_BASE") || "your_maqiatto_username/fiot/garage";
const commandTopic = env.get("MQTT_COMMAND_TOPIC") || `${topicBase}/commands`;
const timestamp = new Date().toISOString();
const deviceId = String(body.device_id || env.get("HARDWARE_DEVICE_ID") || "ESP32-GARAGE-CO-001").trim();
const reason = String(body.reason || "Comando manual desde dashboard").trim().slice(0, 255);
const command = {
  device_id: deviceId,
  timestamp,
  actuator: "VENTILACION",
  action,
  reason,
  source: "node-red-api"
};

const sqlMsg = { ...msg };
sqlMsg.commandPayload = command;
sqlMsg.mqtt_topic = commandTopic;
sqlMsg.topic = `
  INSERT INTO actuator_commands
    (device_id, device_timestamp, actuator, action, reason, source_state, status)
  VALUES (?, ?, ?, ?, ?, ?, ?)
`;
sqlMsg.payload = [deviceId, timestamp, "VENTILACION", action, reason, "MANUAL_API", "PUBLISHED"];

const mqttMsg = { ...msg };
mqttMsg.topic = commandTopic;
mqttMsg.payload = command;

return [null, sqlMsg, mqttMsg];

msg.payload = {
  ok: true,
  command: msg.commandPayload,
  mqtt_topic: msg.mqtt_topic
};
return msg;

msg.statusCode = 204;
msg.payload = "";
return msg;

const origin = env.get("API_CORS_ORIGIN") || "http://localhost:5173";
msg.headers = Object.assign({}, msg.headers || {}, {
  "Access-Control-Allow-Origin": origin,
  "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization",
